mapper.update:
UPDATE iam_identity_provider
SET name = #{name},
    registration_policy = #{registrationPolicy},
    email_auto_link = #{emailAutoLink},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{providerId}
  AND scope_type = #{scopeType}
  AND scope_id IS NOT DISTINCT FROM #{scopeId}
  AND version = #{version}
  AND deleted = 0

UPDATE iam_identity_provider
SET status = #{nextStatus},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{providerId}
  AND scope_type = #{scopeType}
  AND scope_id IS NOT DISTINCT FROM #{scopeId}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND deleted = 0

UPDATE iam_identity_provider
SET updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{providerId}
  AND scope_type = #{scopeType}
  AND scope_id IS NOT DISTINCT FROM #{scopeId}
  AND protocol = #{protocol}
  AND status = 'DISABLED'
  AND version = #{version}
  AND deleted = 0

UPDATE iam_identity_provider provider
SET deleted = 1,
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE provider.id = #{providerId}
  AND provider.scope_type = #{scopeType}
  AND provider.scope_id IS NOT DISTINCT FROM #{scopeId}
  AND provider.status = 'DISABLED'
  AND provider.version = #{version}
  AND provider.deleted = 0
  AND NOT EXISTS (
      SELECT 1
      FROM iam_external_identity external_identity
      WHERE external_identity.provider_id = provider.id
        AND external_identity.deleted = 0
  )
